            self.ctx.ctx,
            &output,
            input.arr,
            self.weights_s.arr,
            self.weights_t.arr,
        );

        if (result != 0) {
            return AccelError.FutharkForwardFailed;
        }

        if (output == null) {
            return AccelError.NullPointer;
        }

        return FutharkArray2DF16{
            .arr = output,
            .rows = input.rows,
            .cols = input.cols,
        };
    }
